"use strict";exports.id=82939,exports.ids=[82939],exports.modules={82939:a=>{a.exports=JSON.parse('{"_status":"machine-draft, needs human review","Addis Ababa Fistula Hospital":"Hospitaala Fistulaa Finfinnee","Alert Hospital – Addis Ababa":"Hospitaala Alert – Finfinnee","Black Lion Hospital (Tikur Anbessa) – Addis Ababa":"Hospitaala Xiqur Anbessaa – Finfinnee","Call emergency services immediately":"Battalumatti tajaajila ariifachiisaa bilbili","Do NOT administer any herbs — proceed to hospital only":"Qoricha biqiltootaa tokkollee hin kenniin — kallattiin gara hospitaalaa qofa deemi","Do NOT give iron tablets without medical supervision":"To\'annoo yaalaa malee kiniinii aayeranii hin kenniin","Emergency Wellbeing Profile | Ethiopian Wisdom Platform":"Ibsa Fayyaa Ariifachiisaa | Waltajjii Ogummaa Itoophiyaa","Ensure patient is lying down in a safe position":"Dhukkubsataan haala nagaa qabuun ciisuu isaa mirkaneessi","Felege Hiwot Referral Hospital – Amhara":"Hospitaala Riferaalaa Falaga Hiwoot – Amaaraa","Give 15g fast-acting carbohydrate: 3–4 tsp sugar dissolved in water":"Kaarbohaayidireetii saffisaan hojjetu giraama 15 kenni: maankaa shaayii 3–4 sukkaara bishaan keessatti bulbulame","Harar Hospital – Harari":"Hospitaala Harar – Hararii","Hawassa University Referral Hospital – Sidama":"Hospitaala Riferaalaa Yuunivarsiitii Hawaasaa – Sidaamaa","Identify and remove allergen source immediately":"Madda alarjii battalumatti adda baasii fageessi","If prescribed epinephrine auto-injector is available, use it":"Yoo lilmoon ofiin of waraanu epinephrine ajajame jiraate, itti fayyadami","If unconscious, place in recovery position (left side)":"Yoo of wallaale, haala fayyinaatti (cinaacha bitaatti) ciibsi","Jimma University Medical Center – Oromia":"Giddugala Yaala Yuunivarsiitii Jimmaa – Oromiyaa","Keep patient warm — blanket if available":"Dhukkubsataa ho\'isi — yoo jiraate uffata itti uwwisi","Kosso/Gesho contraindicated — avoid all herbs during hypoglycemia":"Kosso/Geeshoon hin gorfamu — yeroo sukkaarri dhiigaa gadi bu\'u qorichoota biqiltootaa hunda dhiisi","Lie patient flat — legs elevated unless breathing is difficult":"Dhukkubsataa dugdaan ciibsi — yoo hargansuun hin ulfaanne miilla ol kaasi","Low Blood Sugar Response":"Deebii Sukkaarri Dhiigaa Gadi Bu\'uu","Mekelle Hospital – Tigray":"Hospitaala Maqalee – Tigraay","Recheck in 15 minutes — repeat if not improved":"Daqiiqaa 15 booda irra deebi\'ii mirkaneessi — yoo hin fooyyoofne irra deebi\'i","Seek medical help if unresponsive":"Yoo deebii hin kennine gargaarsa yaalaa barbaadi","Set up your emergency wellbeing profile — contacts, conditions, medications, and blood type — so first responders can act quickly in a wellbeing emergency.":"Ibsa fayyaa ariifachiisaa kee qopheessi — namoota qunnamtii, haala fayyaa, qorichoota fi gosa dhiigaa — akka gargaartonni jalqabaa balaa fayyaa keessatti dafanii hojjetaniif.","Severe Allergic Reaction (Anaphylaxis)":"Deebii Alarjii Cimaa (Anaafilaaksisii)","Severe Anemia Response":"Deebii Dhiigni Hir\'uu Cimaa","St. Paul\'s Hospital Millennium Medical College – Addis Ababa":"Hospitaala Qulqulluu Phaawulos Kolleejjii Yaala Meeleeniyeemii – Finfinnee","Traditional option: 1 tsp honey (ማር) in warm water":"Filannoo aadaa: maankaa shaayii 1 damma bishaan ho\'aa keessatti","Unknown":"Hin beekamu","Yekatit 12 Hospital – Addis Ababa":"Hospitaala Yakkatiit 12 – Finfinnee","⚠️ Do NOT administer herbal remedies during acute crisis":"⚠️ Yeroo rakkoo hamaa qorichoota biqiltootaa hin kenniin"}')}};